import math
def calculate_entropy(probs):
    if abs(sum(probs) - 1.0) > 1e-9:
        raise ValueError('Probabilities must sum to 1')
    entropy = 0.0
    for p in probs:
        if p == 0:
            continue
        entropy -= p * math.log2(p)
    return entropy

